// The same 12-ticket inbox from episode three, plus the knowledge base.
const fs = require('fs');
const path = require('path');
const base = $env.EP03_DIR;
const faq = fs.readFileSync(path.join(base, 'data', 'faq.md'), 'utf8');
const raw = fs.readFileSync(path.join(base, 'data', 'tickets.csv'), 'utf8');
const [, ...lines] = raw.trim().split('\n');
return lines.map((line) => {
  const m = line.match(/^([^,]+),([^,]+),([^,]+),"(.*)"$/);
  return { json: { ticket_id: m[1], customer: m[2], subject: m[3], body: m[4], faq } };
});

// The exact agent from episode three, wrapped in one loop:
// 100 passes over the inbox = 1,200 real model calls. Receipts to disk.
const fs = require('fs');
const path = require('path');
const https = require('https');

const RUNS = Number($env.EP05_RUNS ?? 100);
const outDir = path.join($env.EP05_DIR, 'out');
fs.mkdirSync(outDir, { recursive: true });
const tickets = $input.all().map((i) => i.json);
const faq = tickets[0].faq;

const ask = (payload) => new Promise((resolve, reject) => {
  const body = JSON.stringify(payload);
  const req = https.request({
    hostname: 'fal.run', path: '/fal-ai/any-llm', method: 'POST',
    headers: {
      'Authorization': 'Key ' + $env.FAL_KEY,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  }, (res) => {
    let data = '';
    res.on('data', (c) => (data += c));
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

const t0 = Date.now();
const perRun = [];
let calls = 0, failures = 0;
for (let r = 1; r <= RUNS; r++) {
  let answered = 0, escalated = 0;
  for (const t of tickets) {
    let verdict;
    try {
      const res = await ask({
        model: 'meta-llama/llama-4-scout',
        system_prompt:
          'You are a support agent. Answer ONLY from the knowledge base. ' +
          'Reply as JSON: {"citation": "<TAG or NONE>", "answer": "<reply or ESCALATE>"}. ' +
          'If no knowledge-base entry answers the ticket, citation must be NONE and answer ESCALATE.\n\n' +
          'KNOWLEDGE BASE:\n' + faq,
        prompt: 'TICKET from ' + t.customer + ' (' + t.subject + '): ' + t.body,
      });
      calls++;
      try { verdict = JSON.parse((res.output ?? '').replace(/```json|```/g, '').trim()); }
      catch { verdict = { citation: 'NONE', answer: 'ESCALATE' }; }
    } catch (err) {
      failures++;
      verdict = { citation: 'NONE', answer: 'ESCALATE' };
    }
    const ok = verdict.citation && verdict.citation !== 'NONE' && verdict.answer !== 'ESCALATE';
    if (ok) answered++; else escalated++;
  }
  perRun.push({ run: r, answered, escalated });
  if (r % 5 === 0) {
    fs.writeFileSync(path.join(outDir, 'progress.json'), JSON.stringify({
      done: r, of: RUNS, calls, failures, elapsed_s: Math.round((Date.now() - t0) / 1000),
    }));
  }
}

const byAnswered = {};
for (const p of perRun) byAnswered[p.answered] = (byAnswered[p.answered] ?? 0) + 1;
const summary = {
  runs: RUNS,
  tickets_per_run: tickets.length,
  total_calls: calls,
  network_failures: failures,
  wall_seconds: Math.round((Date.now() - t0) / 1000),
  answered_distribution: byAnswered,
};
fs.writeFileSync(path.join(outDir, 'per-run.json'), JSON.stringify(perRun, null, 2));
fs.writeFileSync(path.join(outDir, 'summary.json'), JSON.stringify(summary, null, 2));
return [{ json: summary }];
